#pragma once
#include "system_research_common.hpp"
#include <random>
namespace kline { namespace system_research {
inline Report tridiagonal_cn_option(const Mat& x,const Vec& p){
    validate(x,1,6,6);parameters(p,4);auto M=count(p[0],4,2000),N=count(p[1],1,100000);double top=positive(p[2]);require(p[3]==0||p[3]==1,"Call flag must be binary");bool call=p[3];require(double(M)*N*x.size()<=1e8,"PDE work limit");Report o{{"Price","GridSpacing","TimeStep","MinimumGridValue","LinearResidual"},{}};for(auto&r:x){double S=positive(r[0]),K=positive(r[1]),rate=r[2],q=r[3],vol=r[4],T=positive(r[5]),ds=top/M,dt=T/N;require(S<top&&K<top&&vol>=0,"Invalid PDE domain");if(vol==0){double f=S*std::exp(-q*T)-K*std::exp(-rate*T);o.rows.push_back({std::max(call?f:-f,0.),ds,dt,0,0});continue;}auto bound=[&](double t){double v=top*std::exp(-q*t)-K*std::exp(-rate*t);return Vec{call?0:K*std::exp(-rate*t),call?std::max(0.,v):std::max(0.,-v)};};Vec V(M+1),a(M+1),b(M+1),c(M+1);for(std::size_t i=0;i<=M;++i){double z=i*ds-K;V[i]=std::max(call?z:-z,0.);if(i&&i<M){double v=vol*vol*i*i,w=(rate-q)*i;a[i]=.5*(v-w);b[i]=-v-rate;c[i]=.5*(v+w);}}double err=0;for(std::size_t t=0;t<N;++t){Vec next(M+1),l(M-1),d(M-1),u(M-1),rhs(M-1);auto bd=bound((t+1)*dt);next[0]=bd[0];next[M]=bd[1];for(std::size_t i=1;i<M;++i){auto j=i-1;l[j]=-.5*dt*a[i];d[j]=1-.5*dt*b[i];u[j]=-.5*dt*c[i];rhs[j]=V[i]+.5*dt*(a[i]*V[i-1]+b[i]*V[i]+c[i]*V[i+1]);}rhs[0]-=l[0]*next[0];rhs.back()-=u.back()*next[M];Vec diag=d,z=rhs;for(std::size_t j=1;j<M-1;++j){require(std::abs(diag[j-1])>1e-14,"Singular PDE pivot");double f=l[j]/diag[j-1];diag[j]-=f*u[j-1];z[j]-=f*z[j-1];}for(std::size_t j=M-1;j-->0;){require(std::abs(diag[j])>1e-14,"Singular PDE pivot");next[j+1]=(z[j]-(j+1<M-1?u[j]*next[j+2]:0))/diag[j];}for(std::size_t j=0;j<M-1;++j){double v=d[j]*next[j+1]+(j?l[j]*next[j]:0)+(j+1<M-1?u[j]*next[j+2]:0);err=std::max(err,std::abs(v-rhs[j]));}V=next;}auto i=std::min(M-1,std::size_t(S/ds));double w=S/ds-i;double price=(1-w)*V[i]+w*V[i+1];o.rows.push_back({price,ds,dt,*std::min_element(V.begin(),V.end()),err});}return o;
}

inline Report asian_geometric_exact(const Mat& x,const Vec& p){
    validate(x,1,6,6);parameters(p,1);double m=count(p[0],1,1000000);Report o{{"Call","Put","LogMean","LogVariance","DiscountedGeometricMean","ParityResidual"},{}};for(auto&r:x){double S=positive(r[0]),K=positive(r[1]),rate=r[2],q=r[3],sig=r[4],T=positive(r[5]);require(sig>=0,"Nonnegative volatility required");double a=std::log(S)+(rate-q-.5*sig*sig)*T*(m+1)/(2*m),v=sig*sig*T*(m+1)*(2*m+1)/(6*m*m),f=positive(std::exp(a+v/2)),df=positive(std::exp(-rate*T)),c,put;if(v==0){c=df*std::max(f-K,0.);put=df*std::max(K-f,0.);}else{double d2=(a-std::log(K))/std::sqrt(v),d1=d2+std::sqrt(v);c=df*(f*normal(d1)-K*normal(d2));put=df*(K*normal(-d2)-f*normal(-d1));}o.rows.push_back({c,put,a,v,df*f,c-put-df*(f-K)});}return o;
}

inline Report asian_arithmetic_control(const Mat& x,const Vec& p){
    validate(x,1,6,6);parameters(p,4);auto m=count(p[0],1,10000),pilot=count(p[1],2,1000000),n=count(p[2],2,2000000),seed=count(p[3],0,1000000000);require(double(m)*(pilot+n)*x.size()<=1e8,"Asian simulation work limit");Report o{{"PlainCall","ControlledCall","PlainSE","ControlledSE","PilotBeta","ExactGeometricCall","VarianceReduction"},{}};for(std::size_t k=0;k<x.size();++k){auto&r=x[k];double S=positive(r[0]),K=positive(r[1]),rate=r[2],q=r[3],sig=r[4],T=positive(r[5]);require(sig>=0,"Nonnegative volatility required");double dt=T/m,df=std::exp(-rate*T),a=std::log(S)+(rate-q-.5*sig*sig)*T*(m+1)/(2*m),v=sig*sig*T*(m+1)*(2.*m+1)/(6.*m*m),f=std::exp(a+v/2),exact=df*std::max(f-K,0.);if(v>0){double d2=(a-std::log(K))/std::sqrt(v);exact=df*(f*normal(d2+std::sqrt(v))-K*normal(d2));}std::mt19937_64 gen(seed+k);std::normal_distribution<double> norm(0,1);auto path=[&](){double l=std::log(S),s=0,g=0;for(std::size_t j=0;j<m;++j){l+=(rate-q-.5*sig*sig)*dt+sig*std::sqrt(dt)*norm(gen);s+=std::exp(l)/m;g+=l/m;}return Vec{df*std::max(s-K,0.),df*std::max(std::exp(g)-K,0.)};};double mx=0,my=0,cov=0,vy=0;for(std::size_t i=1;i<=pilot;++i){Vec z=path();double dx=z[0]-mx,dy=z[1]-my;mx+=dx/i;my+=dy/i;cov+=dx*(z[1]-my);vy+=dy*(z[1]-my);}double beta=vy>0?cov/vy:0;double u=0,w=0,ss=0,tt=0;for(std::size_t i=1;i<=n;++i){Vec z=path();double y=z[0]-beta*(z[1]-exact),du=z[0]-u,dw=y-w;u+=du/i;w+=dw/i;ss+=du*(z[0]-u);tt+=dw*(y-w);}o.rows.push_back({u,w,std::sqrt(std::max(0.,ss)/(n-1)/n),std::sqrt(std::max(0.,tt)/(n-1)/n),beta,exact,ss>0?tt/ss:1});}return o;
}

inline Report cashflow_zspread_fit(const Mat& x,const Vec& p){
    validate(x,1,3,3);parameters(p,4);double market=positive(p[0]),lo=p[1],hi=p[2],tol=positive(p[3]);require(hi>lo,"Invalid spread bracket");double exposure=0;for(auto&r:x){require(r[0]>=0&&r[1]>=0,"Nonnegative time and cash flow required");positive(r[2]);exposure+=r[0]*r[1];}positive(exposure);auto val=[&](double z){Vec v(3,0);for(auto&r:x){double a=r[1]*r[2]*std::exp(-z*r[0]);v[0]+=a;v[1]+=a*r[0];v[2]+=a*r[0]*r[0];}check_finite(v);return v;};require(val(lo)[0]>=market&&val(hi)[0]<=market,"Spread root not bracketed");for(int k=0;k<100;++k){double m=lo/2+hi/2;if(val(m)[0]>market)lo=m;else hi=m;}double z=lo/2+hi/2;Vec v=val(z);require(std::abs(v[0]-market)<=tol*std::max(1.,market),"Spread price residual");return scalar({"ZSpread","ModelPrice","MarketPrice","SpreadDuration","SpreadConvexity","PriceResidual"},{z,v[0],market,v[1]/v[0],v[2]/v[0],v[0]-market});
}

inline Report swap_curve_keyrate(const Mat& x,const Vec& p){
    validate(x,1,3,3);parameters(p,3);double N=positive(p[0]),K=p[1],h=positive(p[2]);require(h<=.01&&x.size()<=2000,"Invalid key-rate controls");double last=0,A=0;for(auto&r:x){require(r[0]>last,"Increasing times required");last=r[0];A+=positive(r[1])*positive(r[2]);}double par=(1-x.back()[1])/A,pv=N*(1-x.back()[1]-K*A);auto value=[&](double z,std::size_t idx){double a=0,d=0;for(std::size_t i=0;i<x.size();++i){auto&r=x[i];double v=r[1]*std::exp((idx==x.size()||idx==i)?-r[0]*z:0);a+=r[2]*v;if(i+1==x.size())d=v;}return N*(1-d-K*a);};double parallel=(value(h,x.size())-value(-h,x.size()))/(2*h),s=0;Report o{{"Node","Time","PV","ParRate","KeyRateDerivative","ParallelDerivative","ConservationResidual"},{}};for(std::size_t i=0;i<x.size();++i){double d=(value(h,i)-value(-h,i))/(2*h);s+=d;o.rows.push_back({double(i+1),x[i][0],pv,par,d,parallel,0});}for(auto&r:o.rows)r[6]=std::abs(s-parallel);return o;
}

inline Report credit_tranche_loss(const Mat& x,const Vec& p){
    validate(x,1,2,2);require(p.size()>=2&&p.size()<=65,"Invalid tranche grid");parameters(p,p.size());require(p.front()==0&&p.back()==1,"Full loss waterfall required");for(std::size_t j=1;j<p.size();++j)require(p[j]>p[j-1],"Increasing tranche thresholds required");double mass=0,el=0;for(auto&r:x){require(r[0]>=0&&r[1]>=0&&r[1]<=1,"Invalid loss scenario");mass+=r[0];el+=r[0]*r[1];}require(std::abs(mass-1)<=1e-10,"Scenario mass must sum to one");Report o{{"Tranche","Attachment","Detachment","ExpectedLoss","ExpectedLossRate","PortfolioExpectedLoss","ConservationResidual"},{}};double s=0;for(std::size_t j=1;j<p.size();++j){double width=p[j]-p[j-1],v=0;for(auto&r:x)v+=r[0]*std::clamp(r[1]-p[j-1],0.,width);s+=v;o.rows.push_back({double(j),p[j-1],p[j],v,v/width,el,0});}for(auto&r:o.rows)r[6]=std::abs(s-el);return o;
}
} }
